-- Replace the email placeholder below before running this file in Supabase SQL Editor.
BEGIN;
SELECT set_config('ofir.setup_email','REPLACE_WITH_OFIR_GOOGLE_EMAIL',true);

-- PostgreSQL/Supabase schema. Keep local SQLite development data untouched.
CREATE TABLE IF NOT EXISTS public.companies (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, location_hint TEXT NOT NULL,
 suggested_url TEXT NOT NULL, career_url TEXT NOT NULL, ats_hint TEXT NOT NULL,
 ats_identifier TEXT NOT NULL, imported_active INTEGER NOT NULL,
 imported_priority TEXT NOT NULL, imported_last_checked TEXT NOT NULL,
 imported_last_result TEXT NOT NULL, notes TEXT NOT NULL, enabled INTEGER NOT NULL,
 source_status TEXT NOT NULL DEFAULT 'pending', last_checked TEXT,
 last_result TEXT NOT NULL DEFAULT 'טרם נבדק במערכת החדשה', job_count INTEGER,
 verified_url TEXT
);
CREATE TABLE IF NOT EXISTS public.scans (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id TEXT NOT NULL REFERENCES public.companies(id),
 started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL,
 fetched_count INTEGER, eligible_count INTEGER, new_count INTEGER, message TEXT
);
CREATE TABLE IF NOT EXISTS public.jobs (
 id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES public.companies(id),
 source_id TEXT NOT NULL, title TEXT NOT NULL, location TEXT NOT NULL,
 work_model TEXT NOT NULL DEFAULT 'לא צוין', url TEXT NOT NULL UNIQUE,
 description TEXT NOT NULL, published_at TEXT, updated_at TEXT,
 first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, last_verified_at TEXT,
 status TEXT NOT NULL DEFAULT 'unverified', score INTEGER NOT NULL CHECK (score BETWEEN 0 AND 100),
 breakdown TEXT NOT NULL, reasons TEXT NOT NULL, gaps TEXT NOT NULL,
 experience TEXT NOT NULL, eligible INTEGER NOT NULL CHECK (eligible IN (0,1)), exclusion_reason TEXT,
 content_hash TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1,
 fit TEXT NOT NULL DEFAULT 'unrated' CHECK (fit IN ('unrated','yes','maybe','no')), familiar INTEGER NOT NULL DEFAULT 0 CHECK (familiar IN (0,1)),
 application_status TEXT NOT NULL DEFAULT 'not_applied' CHECK (application_status IN ('not_applied','planned','applied','interviewing','rejected','withdrawn')), personal_note TEXT NOT NULL DEFAULT '' CHECK (length(personal_note)<=2000),
 user_updated_at TEXT
);
CREATE TABLE IF NOT EXISTS public.job_events (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, job_id TEXT NOT NULL REFERENCES public.jobs(id),
 version INTEGER NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL,
 notified_at TEXT, UNIQUE(job_id, version)
);
CREATE TABLE IF NOT EXISTS public.imports (
 canonical_url TEXT PRIMARY KEY, application_status TEXT NOT NULL,
 applied_at TEXT, imported_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS public.digest_runs (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, day TEXT NOT NULL UNIQUE,
 status TEXT NOT NULL, created_at TEXT NOT NULL, sent_at TEXT
);
CREATE INDEX IF NOT EXISTS jobs_company ON public.jobs(company_id);
CREATE INDEX IF NOT EXISTS events_pending ON public.job_events(notified_at);
CREATE UNIQUE INDEX IF NOT EXISTS scans_source_start ON public.scans(company_id,started_at);

-- Run as the Supabase database owner. No application/browser role can edit the allowlist.
CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated;
CREATE TABLE IF NOT EXISTS private.ofir_owner (
 singleton BOOLEAN PRIMARY KEY DEFAULT true CHECK (singleton),
 email TEXT NOT NULL CHECK (email=lower(email))
);
ALTER TABLE private.ofir_owner ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.ofir_owner FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION private.configure_owner(owner_email TEXT)
RETURNS VOID LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF owner_email IS NULL OR owner_email NOT LIKE '%@%.%' OR owner_email LIKE '%example.invalid%' THEN
   RAISE EXCEPTION 'Set a valid Google email for the app owner before running setup';
 END IF;
 INSERT INTO private.ofir_owner(singleton,email) VALUES(true,lower(trim(owner_email)))
 ON CONFLICT(singleton) DO UPDATE SET email=excluded.email;
END;
$$;
REVOKE ALL ON FUNCTION private.configure_owner(TEXT) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.ofir_is_owner()
RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT auth.uid() IS NOT NULL AND auth.jwt()->'app_metadata'->>'provider'='google' AND EXISTS (
   SELECT 1 FROM private.ofir_owner WHERE email=lower(auth.jwt()->>'email')
 );
$$;
REVOKE ALL ON FUNCTION public.ofir_is_owner() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.ofir_is_owner() TO authenticated;

ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.scans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.job_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.imports ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.digest_runs ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.companies,public.jobs,public.scans,public.job_events,public.imports,public.digest_runs
 FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.companies,public.jobs TO authenticated;
GRANT UPDATE(fit,familiar,application_status,personal_note,user_updated_at) ON public.jobs TO authenticated;
GRANT ALL ON public.companies,public.jobs,public.scans,public.job_events,public.imports,public.digest_runs TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.scans_id_seq,public.job_events_id_seq,public.digest_runs_id_seq TO service_role;

DROP POLICY IF EXISTS ofir_read_companies ON public.companies;
CREATE POLICY ofir_read_companies ON public.companies FOR SELECT TO authenticated USING ((SELECT public.ofir_is_owner()));
DROP POLICY IF EXISTS ofir_read_jobs ON public.jobs;
CREATE POLICY ofir_read_jobs ON public.jobs FOR SELECT TO authenticated USING ((SELECT public.ofir_is_owner()));
DROP POLICY IF EXISTS ofir_update_feedback ON public.jobs;
CREATE POLICY ofir_update_feedback ON public.jobs FOR UPDATE TO authenticated
 USING ((SELECT public.ofir_is_owner())) WITH CHECK ((SELECT public.ofir_is_owner()));

-- Additive matching metadata; existing feedback, scores and access rules are retained.
ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS match_category TEXT DEFAULT 'unassessed'
 CHECK (match_category IN ('unassessed','priority','review','gap'));
ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS match_version TEXT DEFAULT '';
ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS match_details TEXT DEFAULT '{}';

-- Narrow, transaction-safe write operations for the trusted collector only.
CREATE OR REPLACE FUNCTION public.ofir_sync(payload JSONB)
RETURNS VOID LANGUAGE plpgsql SET search_path='' AS $$
DECLARE c public.companies; j public.jobs; s public.scans; e public.job_events; i public.imports; d public.digest_runs; finding JSONB;
BEGIN
 PERFORM pg_catalog.pg_advisory_xact_lock(4801739);
 FOR c IN SELECT * FROM jsonb_populate_recordset(NULL::public.companies,COALESCE(payload->'companies','[]')) LOOP
   INSERT INTO public.companies SELECT c.* ON CONFLICT(id) DO UPDATE SET
     source_status=excluded.source_status,last_checked=excluded.last_checked,last_result=excluded.last_result,
     job_count=excluded.job_count,verified_url=excluded.verified_url
     WHERE companies.last_checked IS NULL OR excluded.last_checked>=companies.last_checked;
 END LOOP;
 FOR j IN SELECT * FROM jsonb_populate_recordset(NULL::public.jobs,COALESCE(payload->'jobs','[]')) LOOP
   INSERT INTO public.jobs SELECT j.* ON CONFLICT(id) DO UPDATE SET
     source_id=excluded.source_id,title=excluded.title,location=excluded.location,work_model=excluded.work_model,
     url=excluded.url,description=excluded.description,published_at=excluded.published_at,updated_at=excluded.updated_at,
     last_seen_at=excluded.last_seen_at,last_verified_at=excluded.last_verified_at,status=excluded.status,
     score=excluded.score,breakdown=excluded.breakdown,reasons=excluded.reasons,gaps=excluded.gaps,
     experience=excluded.experience,eligible=excluded.eligible,exclusion_reason=excluded.exclusion_reason,
     content_hash=excluded.content_hash,version=excluded.version,
     match_category=COALESCE(excluded.match_category,jobs.match_category),
     match_version=COALESCE(excluded.match_version,jobs.match_version),
     match_details=COALESCE(excluded.match_details,jobs.match_details)
     WHERE excluded.last_seen_at>=jobs.last_seen_at
       AND (COALESCE(jobs.match_version,'')='' OR COALESCE(excluded.match_version,'')<>'');
   -- Feedback, application status, personal notes and first_seen_at are preserved on updates.
 END LOOP;
 FOR e IN SELECT * FROM jsonb_populate_recordset(NULL::public.job_events,COALESCE(payload->'job_events','[]')) LOOP
   INSERT INTO public.job_events(job_id,version,kind,created_at,notified_at)
    SELECT e.job_id,e.version,e.kind,e.created_at,e.notified_at
    WHERE EXISTS(SELECT 1 FROM public.jobs WHERE id=e.job_id AND version>=e.version)
    ON CONFLICT(job_id,version) DO NOTHING;
 END LOOP;
 FOR s IN SELECT * FROM jsonb_populate_recordset(NULL::public.scans,COALESCE(payload->'scans','[]')) LOOP
   INSERT INTO public.scans(company_id,started_at,finished_at,status,fetched_count,eligible_count,new_count,message)
   VALUES(s.company_id,s.started_at,s.finished_at,s.status,s.fetched_count,s.eligible_count,s.new_count,s.message)
   ON CONFLICT(company_id,started_at) DO NOTHING;
 END LOOP;
 FOR i IN SELECT * FROM jsonb_populate_recordset(NULL::public.imports,COALESCE(payload->'imports','[]')) LOOP
   INSERT INTO public.imports SELECT i.* ON CONFLICT(canonical_url) DO UPDATE SET
    application_status=excluded.application_status,applied_at=excluded.applied_at,imported_at=excluded.imported_at
    WHERE excluded.imported_at>=imports.imported_at;
 END LOOP;
 FOR d IN SELECT * FROM jsonb_populate_recordset(NULL::public.digest_runs,COALESCE(payload->'digest_runs','[]')) LOOP
   INSERT INTO public.digest_runs(day,status,created_at,sent_at) VALUES(d.day,d.status,d.created_at,d.sent_at)
   ON CONFLICT(day) DO NOTHING;
 END LOOP;
 FOR finding IN SELECT * FROM jsonb_array_elements(COALESCE(payload->'company_monitor_controls','[]')) LOOP
   INSERT INTO public.company_monitor_controls SELECT * FROM jsonb_populate_record(NULL::public.company_monitor_controls,finding)
   ON CONFLICT(company_id) DO NOTHING;
 END LOOP;
 FOR finding IN SELECT * FROM jsonb_array_elements(COALESCE(payload->'job_discoveries','[]')) LOOP
   INSERT INTO public.job_discoveries SELECT * FROM jsonb_populate_record(NULL::public.job_discoveries,finding)
   ON CONFLICT(url) DO UPDATE SET status=excluded.status,linked_job_id=excluded.linked_job_id,
    last_checked=excluded.last_checked,last_result=excluded.last_result
    WHERE excluded.last_checked IS NOT NULL AND (job_discoveries.last_checked IS NULL OR excluded.last_checked>=job_discoveries.last_checked)
      AND NOT(job_discoveries.status='linked' AND excluded.status='pending');
 END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION public.ofir_reserve_digest(digest_day TEXT, stamp TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SET search_path='' AS $$
DECLARE changed INTEGER;
BEGIN
 INSERT INTO public.digest_runs(day,status,created_at) VALUES(digest_day,'sending',stamp)
 ON CONFLICT(day) DO NOTHING;
 GET DIAGNOSTICS changed=ROW_COUNT;
 RETURN changed=1;
END;
$$;

CREATE OR REPLACE FUNCTION public.ofir_finish_digest(digest_day TEXT, outcome TEXT, stamp TEXT, events JSONB)
RETURNS VOID LANGUAGE plpgsql SET search_path='' AS $$
DECLARE e JSONB;
BEGIN
 IF outcome NOT IN ('sent','uncertain') THEN RAISE EXCEPTION 'Invalid digest outcome'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.digest_runs WHERE day=digest_day AND status='sending') THEN
   RAISE EXCEPTION 'Digest is not reserved';
 END IF;
 IF outcome='sent' THEN
   FOR e IN SELECT * FROM jsonb_array_elements(events) LOOP
     UPDATE public.job_events SET notified_at=stamp WHERE job_id=e->>'job_id' AND version=(e->>'version')::INTEGER;
   END LOOP;
 END IF;
 UPDATE public.digest_runs SET status=outcome,sent_at=CASE WHEN outcome='sent' THEN stamp ELSE NULL END WHERE day=digest_day;
END;
$$;

CREATE OR REPLACE FUNCTION public.ofir_import_applications(records JSONB)
RETURNS VOID LANGUAGE plpgsql SET search_path='' AS $$
DECLARE i public.imports;
BEGIN
 FOR i IN SELECT * FROM jsonb_populate_recordset(NULL::public.imports,records) LOOP
   IF i.application_status NOT IN ('not_applied','planned','applied','interviewing','rejected','withdrawn')
     OR i.canonical_url NOT LIKE 'https://%' THEN RAISE EXCEPTION 'Invalid import record'; END IF;
   INSERT INTO public.imports SELECT i.* ON CONFLICT(canonical_url) DO UPDATE SET
    application_status=excluded.application_status,applied_at=excluded.applied_at,imported_at=excluded.imported_at;
   UPDATE public.jobs SET application_status=i.application_status,familiar=1,user_updated_at=i.imported_at
    WHERE url=i.canonical_url;
 END LOOP;
END;
$$;

REVOKE ALL ON FUNCTION public.ofir_sync(JSONB),public.ofir_reserve_digest(TEXT,TEXT),
 public.ofir_finish_digest(TEXT,TEXT,TEXT,JSONB),public.ofir_import_applications(JSONB)
 FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ofir_sync(JSONB),public.ofir_reserve_digest(TEXT,TEXT),
 public.ofir_finish_digest(TEXT,TEXT,TEXT,JSONB),public.ofir_import_applications(JSONB) TO service_role;

-- Additive upgrade. Existing owner configuration, jobs, feedback and history are retained.
CREATE TABLE IF NOT EXISTS public.company_monitor_controls (
 company_id TEXT PRIMARY KEY REFERENCES public.companies(id), opted_out INTEGER NOT NULL CHECK(opted_out IN (0,1))
);
ALTER TABLE public.company_monitor_controls ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.company_monitor_controls FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.company_monitor_controls TO authenticated;
GRANT ALL ON public.company_monitor_controls TO service_role;
DROP POLICY IF EXISTS ofir_read_monitor_controls ON public.company_monitor_controls;
CREATE POLICY ofir_read_monitor_controls ON public.company_monitor_controls FOR SELECT TO authenticated USING((SELECT public.ofir_is_owner()));
CREATE TABLE IF NOT EXISTS public.job_discoveries (
 id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES public.companies(id),
 company_name TEXT NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL UNIQUE,
 location_hint TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '',
 added_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','linked')),
 linked_job_id TEXT REFERENCES public.jobs(id), last_checked TEXT,
 last_result TEXT NOT NULL DEFAULT 'ממצא שיובא — טרם אומת במקור הרשמי'
);
ALTER TABLE public.job_discoveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.job_discoveries FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.job_discoveries TO authenticated;
GRANT ALL ON public.job_discoveries TO service_role;
DROP POLICY IF EXISTS ofir_read_discoveries ON public.job_discoveries;
CREATE POLICY ofir_read_discoveries ON public.job_discoveries FOR SELECT TO authenticated USING((SELECT public.ofir_is_owner()));

CREATE OR REPLACE FUNCTION private.clean_source_url(value TEXT,optional BOOLEAN DEFAULT false)
RETURNS TEXT LANGUAGE plpgsql SET search_path='' AS $$
DECLARE base TEXT; authority TEXT; query TEXT; path TEXT;
BEGIN
 IF optional AND coalesce(value,'')='' THEN RETURN ''; END IF;
 value:=btrim(value);
 IF value IS NULL OR length(value)>2000 OR value ~ '[[:space:][:cntrl:]]' OR value !~ '^https://([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}(/|\?|#|$)' THEN RAISE EXCEPTION 'A public HTTPS URL is required'; END IF;
 authority:=lower(substring(value FROM '^https://([^/?#]+)'));
 IF authority ~ '\.(local|internal|localhost|test|invalid)$' THEN RAISE EXCEPTION 'Private hosts are not supported'; END IF;
 value:=split_part(value,'#',1);
 path:=regexp_replace(split_part(value,'?',1),'^https://[^/?#]+','');
 path:=regexp_replace(path,'/+$','');
 base:='https://'||authority||path;
 IF position('?' IN value)>0 THEN
   SELECT string_agg(part,'&' ORDER BY part) INTO query FROM unnest(string_to_array(split_part(value,'?',2),'&')) part
    WHERE part<>'' AND lower(split_part(part,'=',1)) !~ '^utm_' AND lower(split_part(part,'=',1)) NOT IN ('source','ref','gh_src','fbclid','gclid');
 END IF;
 RETURN base||CASE WHEN coalesce(query,'')<>'' THEN '?'||query ELSE '' END;
END;
$$;
REVOKE ALL ON FUNCTION private.clean_source_url(TEXT,BOOLEAN) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.ofir_add_discoveries(payload JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c JSONB; j JSONB; label TEXT; career TEXT; target_id TEXT; target_url TEXT; ats TEXT; identifier TEXT;
 added_companies INTEGER:=0; added_jobs INTEGER:=0; changed INTEGER;
BEGIN
 IF NOT coalesce(public.ofir_is_owner(),false) AND coalesce(auth.jwt()->>'role','')<>'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF;
 IF jsonb_typeof(coalesce(payload->'companies','[]'))<>'array' OR jsonb_typeof(coalesce(payload->'jobs','[]'))<>'array'
   OR jsonb_array_length(coalesce(payload->'companies','[]'))+jsonb_array_length(coalesce(payload->'jobs','[]')) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Import must contain 1 to 100 findings'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(4801739);
 FOR c IN SELECT * FROM jsonb_array_elements(coalesce(payload->'companies','[]')) UNION ALL
  SELECT jsonb_build_object('name',v->>'company') FROM jsonb_array_elements(coalesce(payload->'jobs','[]')) v LOOP
   label:=btrim(c->>'name');
   IF label IS NULL OR length(label) NOT BETWEEN 1 AND 200 OR length(coalesce(c->>'notes',''))>4000 OR length(coalesce(c->>'location',''))>250 THEN RAISE EXCEPTION 'Invalid company'; END IF;
   career:=private.clean_source_url(c->>'career_url',true);
   ats:='Generic HTML'; identifier:='';
   IF career ~ '^https://(www\.)?comeet\.(com|co)/jobs/' THEN ats:='Comeet'; END IF;
   IF career ~ '^https://(job-boards(\.eu)?|boards)\.greenhouse\.io/[^/?]+' THEN
     ats:='Greenhouse'; identifier:=split_part(regexp_replace(career,'^https://[^/]+/',''), '/',1);
   END IF;
   SELECT id INTO target_id FROM public.companies WHERE lower(btrim(name))=lower(label) ORDER BY id LIMIT 1;
   IF target_id IS NOT NULL THEN
     UPDATE public.companies SET career_url=career,ats_hint=ats,ats_identifier=identifier WHERE id=target_id AND career_url='' AND career<>'';
     CONTINUE;
   END IF;
   INSERT INTO public.companies(id,name,location_hint,suggested_url,career_url,ats_hint,ats_identifier,imported_active,
    imported_priority,imported_last_checked,imported_last_result,notes,enabled)
    VALUES(substr(md5(lower(label)),1,16),label,coalesce(c->>'location',''),career,career,ats,identifier,0,'Medium','','',coalesce(c->>'notes',''),0)
    ON CONFLICT(id) DO NOTHING;
   GET DIAGNOSTICS changed=ROW_COUNT; added_companies:=added_companies+changed;
 END LOOP;
 FOR j IN SELECT * FROM jsonb_array_elements(coalesce(payload->'jobs','[]')) LOOP
   IF length(coalesce(j->>'title','')) NOT BETWEEN 1 AND 250 OR length(coalesce(j->>'notes',''))>4000 OR length(coalesce(j->>'location',''))>250 THEN RAISE EXCEPTION 'Invalid job finding'; END IF;
   target_url:=private.clean_source_url(j->>'url');
   SELECT id INTO target_id FROM public.companies WHERE lower(btrim(name))=lower(btrim(j->>'company')) ORDER BY id LIMIT 1;
   INSERT INTO public.job_discoveries(id,company_id,company_name,title,url,location_hint,notes,added_at)
    VALUES(substr(md5(target_url),1,24),target_id,btrim(j->>'company'),btrim(j->>'title'),target_url,coalesce(j->>'location',''),coalesce(j->>'notes',''),to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"+00:00"'))
    ON CONFLICT(url) DO NOTHING;
   GET DIAGNOSTICS changed=ROW_COUNT; added_jobs:=added_jobs+changed;
 END LOOP;
 RETURN jsonb_build_object('companies_added',added_companies,'jobs_added',added_jobs);
END;
$$;
REVOKE ALL ON FUNCTION public.ofir_add_discoveries(JSONB) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ofir_add_discoveries(JSONB) TO authenticated,service_role;

CREATE OR REPLACE FUNCTION public.ofir_set_monitor(target_id TEXT,monitor BOOLEAN)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT coalesce(public.ofir_is_owner(),false) THEN RAISE EXCEPTION 'Forbidden'; END IF;
 IF monitor AND NOT EXISTS(SELECT 1 FROM public.companies WHERE id=target_id AND career_url<>'') THEN RAISE EXCEPTION 'Add a career URL first'; END IF;
 UPDATE public.companies SET enabled=CASE WHEN monitor THEN 1 ELSE 0 END WHERE id=target_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Company not found'; END IF;
 INSERT INTO public.company_monitor_controls(company_id,opted_out) VALUES(target_id,CASE WHEN monitor THEN 0 ELSE 1 END)
 ON CONFLICT(company_id) DO UPDATE SET opted_out=excluded.opted_out;
END;
$$;
REVOKE ALL ON FUNCTION public.ofir_set_monitor(TEXT,BOOLEAN) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ofir_set_monitor(TEXT,BOOLEAN) TO authenticated;

CREATE OR REPLACE FUNCTION public.ofir_enable_sources(ids JSONB)
RETURNS JSONB LANGUAGE SQL SET search_path='' AS $$
 WITH activated AS (UPDATE public.companies SET enabled=1 WHERE id IN (SELECT jsonb_array_elements_text(ids)) AND enabled=0 AND last_checked IS NULL
  AND NOT EXISTS(SELECT 1 FROM public.company_monitor_controls m WHERE m.company_id=companies.id AND m.opted_out=1) RETURNING id)
 SELECT coalesce(jsonb_agg(id),'[]'::jsonb) FROM activated;
$$;
REVOKE ALL ON FUNCTION public.ofir_enable_sources(JSONB) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ofir_enable_sources(JSONB) TO service_role;

CREATE OR REPLACE FUNCTION public.ofir_link_discoveries()
RETURNS VOID LANGUAGE SQL SET search_path='' AS $$
 UPDATE public.job_discoveries d SET linked_job_id=j.id,status='linked',last_checked=j.last_verified_at,
  last_result='הממצא קושר למשרה שנאספה ואומתה במקור הרשמי'
 FROM public.jobs j WHERE d.company_id=j.company_id AND d.url=j.url AND j.status='open' AND j.last_verified_at IS NOT NULL;
$$;
REVOKE ALL ON FUNCTION public.ofir_link_discoveries() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ofir_link_discoveries() TO service_role;

-- Additive scheduling only: no job reseed, deletion, rescore, or owner change.
CREATE TABLE IF NOT EXISTS public.scheduled_slots (
 id TEXT PRIMARY KEY, local_day DATE NOT NULL, slot_name TEXT NOT NULL CHECK(slot_name IN ('morning','evening')),
 target_at TIMESTAMPTZ NOT NULL, deadline_at TIMESTAMPTZ NOT NULL,
 state TEXT NOT NULL DEFAULT 'retry_wait' CHECK(state IN ('running','retry_wait','completed','failed')),
 company_ids JSONB CHECK(company_ids IS NULL OR jsonb_typeof(company_ids)='array'), deferred_count INTEGER NOT NULL DEFAULT 0,
 attempt_token TEXT, lease_until TIMESTAMPTZ, claims INTEGER NOT NULL DEFAULT 0,
 run_id TEXT, commit_sha TEXT, actual_start TIMESTAMPTZ, finished_at TIMESTAMPTZ,
 reason TEXT, UNIQUE(local_day,slot_name)
);
ALTER TABLE public.scans ADD COLUMN IF NOT EXISTS scheduled_slot_id TEXT REFERENCES public.scheduled_slots(id);
ALTER TABLE public.scans ADD COLUMN IF NOT EXISTS scheduled_attempt TEXT;
ALTER TABLE public.scans ADD COLUMN IF NOT EXISTS retry_kind TEXT;
ALTER TABLE public.scans ADD COLUMN IF NOT EXISTS retry_after TIMESTAMPTZ;
ALTER TABLE public.scans ADD COLUMN IF NOT EXISTS checkpoint_receipt JSONB;
CREATE UNIQUE INDEX IF NOT EXISTS scans_scheduled_attempt ON public.scans(scheduled_slot_id,company_id,scheduled_attempt)
 WHERE scheduled_slot_id IS NOT NULL;
ALTER TABLE public.scheduled_slots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.scheduled_slots FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.scheduled_slots TO service_role;

-- The existing per-company scans are the retry ledger; no second work queue.
CREATE OR REPLACE FUNCTION public.ofir_scheduled_report(slot_id TEXT)
RETURNS JSONB LANGUAGE plpgsql SET search_path='' AS $$
DECLARE slot public.scheduled_slots; company TEXT; c public.companies; latest public.scans;
 n INTEGER; successes INTEGER; streak INTEGER; cooldown TIMESTAMPTZ; ready TIMESTAMPTZ;
 kind TEXT; details JSONB:='[]'; item JSONB; totals JSONB;
BEGIN
 SELECT * INTO STRICT slot FROM public.scheduled_slots WHERE id=slot_id;
 FOR company IN SELECT jsonb_array_elements_text(coalesce(slot.company_ids,'[]')) LOOP
  SELECT * INTO c FROM public.companies WHERE id=company;
  SELECT count(*),count(*) FILTER(WHERE status IN ('ok','empty')) INTO n,successes
   FROM public.scans WHERE scheduled_slot_id=slot_id AND company_id=company;
  SELECT * INTO latest FROM public.scans WHERE scheduled_slot_id=slot_id AND company_id=company ORDER BY id DESC LIMIT 1;
  -- Two consecutive exhausted slots cause a 24h cooldown, then one recovery probe.
  SELECT count(*) FILTER(WHERE exhausted),max(ended) FILTER(WHERE exhausted)+interval '24 hours'
   INTO streak,cooldown FROM (
    SELECT (count(*)>=3 OR bool_or(s.retry_kind='permanent') OR bool_or(t.state='failed'))
     AND NOT bool_or(s.status IN ('ok','empty')) AS exhausted,
     max(s.finished_at::timestamptz) AS ended
    FROM public.scans s JOIN public.scheduled_slots t ON t.id=s.scheduled_slot_id
    WHERE s.company_id=company AND t.target_at<slot.target_at
    GROUP BY t.id,t.target_at ORDER BY t.target_at DESC LIMIT 2
   ) history;
  ready:=CASE WHEN streak=2 THEN cooldown ELSE NULL END;
  IF latest.retry_after IS NOT NULL THEN ready:=greatest(ready,latest.retry_after); END IF;
  kind:=CASE
   WHEN successes>0 THEN 'checked'
   WHEN c.enabled<>1 OR EXISTS(SELECT 1 FROM public.company_monitor_controls m WHERE m.company_id=company AND m.opted_out=1) THEN 'waived'
   WHEN latest.status='running' THEN 'running'
   WHEN n>=CASE WHEN streak=2 THEN 1 ELSE 3 END OR latest.retry_kind='permanent' THEN 'exhausted'
   WHEN ready>=slot.deadline_at THEN 'exhausted'
   WHEN ready>clock_timestamp() THEN 'pending_retry'
   ELSE 'ready' END;
  item:=jsonb_build_object('company_id',company,'company',c.name,'state',kind,'attempts',n,
    'last_scan_id',latest.id,'checkpoint_confirmed',latest.checkpoint_receipt IS NOT NULL,
    'retry_at',ready,'source_status',latest.status,'message',latest.message,'retry_kind',latest.retry_kind);
  details:=details||jsonb_build_array(item);
 END LOOP;
 SELECT jsonb_build_object(
  'jobs_extracted',coalesce(sum(fetched_count),0),'jobs_discovered',coalesce(sum(new_count),0),
  'jobs_inserted',coalesce(sum((checkpoint_receipt->>'inserted')::integer),0),
  'jobs_updated',coalesce(sum((checkpoint_receipt->>'updated')::integer),0),
  'source_failures',count(*) FILTER(WHERE status NOT IN ('ok','empty','running')),
  'companies_attempted',count(DISTINCT company_id), 'source_attempts',count(*)) INTO totals
 FROM public.scans WHERE scheduled_slot_id=slot_id;
 RETURN to_jsonb(slot)||totals||jsonb_build_object('companies',details,
  'selected',jsonb_array_length(coalesce(slot.company_ids,'[]')),
  'checked',(SELECT count(*) FROM jsonb_array_elements(details) d WHERE d->>'state'='checked'),
  'waived',(SELECT count(*) FROM jsonb_array_elements(details) d WHERE d->>'state'='waived'),
  'exhausted',(SELECT count(*) FROM jsonb_array_elements(details) d WHERE d->>'state'='exhausted'),
  'pending_retry',(SELECT count(*) FROM jsonb_array_elements(details) d WHERE d->>'state' IN ('ready','running','pending_retry')),
  'persistence','confirmed');
END;
$$;

CREATE OR REPLACE FUNCTION public.ofir_claim_scheduled(worker_token TEXT, workflow_run TEXT, sha TEXT)
RETURNS JSONB LANGUAGE plpgsql SET search_path='' AS $$
DECLARE slot public.scheduled_slots; observed_at TIMESTAMPTZ:=clock_timestamp(); expired JSONB;
 candidate RECORD; report JSONB;
BEGIN
 IF coalesce(length(worker_token),0) NOT BETWEEN 16 AND 100 THEN RAISE EXCEPTION 'Invalid attempt token'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(4801740);
 observed_at:=clock_timestamp();
 -- Targets are civil Israeli times; elapsed horizon uses timestamptz, including DST days.
 FOR candidate IN
  SELECT day::date AS day,name,((day::date+hour::time) AT TIME ZONE 'Asia/Jerusalem') AS target
  FROM generate_series(coalesce((SELECT max(local_day) FROM public.scheduled_slots),
   (observed_at AT TIME ZONE 'Asia/Jerusalem')::date-1),
   (observed_at AT TIME ZONE 'Asia/Jerusalem')::date,interval '1 day') day
  CROSS JOIN (VALUES ('morning','08:17'),('evening','17:17')) hours(name,hour)
 LOOP
  IF candidate.target<=observed_at THEN
   INSERT INTO public.scheduled_slots(id,local_day,slot_name,target_at,deadline_at)
    VALUES(candidate.day||'/'||candidate.name,candidate.day,candidate.name,candidate.target,candidate.target+interval '24 hours')
    ON CONFLICT DO NOTHING;
  END IF;
 END LOOP;
 -- A cancelled finalizer must not turn fully checkpointed work into a missed slot.
 UPDATE public.scheduled_slots t SET state='completed',reason='completion_recovered',finished_at=observed_at,lease_until=NULL
 WHERE state IN ('running','retry_wait') AND (lease_until IS NULL OR lease_until<=observed_at)
  AND jsonb_array_length(coalesce(company_ids,'[]'))>0
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.ofir_scheduled_report(t.id)->'companies') d
   WHERE d->>'state' NOT IN ('checked','waived'));
 WITH changed AS (
  UPDATE public.scheduled_slots SET state='failed',reason=CASE WHEN deadline_at<=observed_at THEN 'recovery_deadline_exceeded' ELSE 'claim_limit_exceeded' END,finished_at=observed_at,
   lease_until=NULL WHERE (deadline_at<=observed_at OR claims>=24) AND state IN ('running','retry_wait')
   AND (lease_until IS NULL OR lease_until<=observed_at) RETURNING id
 ) SELECT coalesce(jsonb_agg(id),'[]') INTO expired FROM changed;
 -- Lost claim acknowledgements replay the same token without creating a new attempt.
 SELECT * INTO slot FROM public.scheduled_slots WHERE attempt_token=worker_token AND state='running' AND lease_until>observed_at FOR UPDATE;
 IF FOUND THEN RETURN jsonb_build_object('outcome','claimed','slot',public.ofir_scheduled_report(slot.id),'expired_slots',expired); END IF;
 IF EXISTS(SELECT 1 FROM public.scheduled_slots WHERE state='running' AND lease_until>observed_at) THEN
  RETURN jsonb_build_object('outcome','skipped','reason','lease_owned','slot',public.ofir_scheduled_report((SELECT id FROM public.scheduled_slots WHERE state='running' AND lease_until>observed_at ORDER BY target_at DESC LIMIT 1)),'expired_slots',expired);
 END IF;
 -- Initial slots before retries; a newly due slot cannot be starved by old failures.
 FOR slot IN SELECT * FROM public.scheduled_slots WHERE state IN ('running','retry_wait') AND deadline_at>observed_at
  AND claims<24 ORDER BY (company_ids IS NULL) DESC,target_at DESC FOR UPDATE LOOP
  -- Cancelled workers consumed an attempt, but cannot overwrite a successor's result.
  UPDATE public.scans SET status='error',retry_kind='transient',message='Worker lease expired before checkpoint',
   finished_at=observed_at::text,retry_after=observed_at+interval '1 hour'
   WHERE scheduled_slot_id=slot.id AND status='running';
  report:=public.ofir_scheduled_report(slot.id);
  IF slot.company_ids IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(report->'companies') d WHERE d->>'state'='ready') THEN
   IF (report->>'pending_retry')::integer=0 THEN
    UPDATE public.scheduled_slots SET state=CASE WHEN (report->>'exhausted')::integer>0 OR (report->>'selected')::integer=0 THEN 'failed' ELSE 'completed' END,
     lease_until=NULL,finished_at=observed_at WHERE id=slot.id;
   ELSE
    UPDATE public.scheduled_slots SET state='retry_wait',lease_until=NULL WHERE id=slot.id;
   END IF;
   CONTINUE;
  END IF;
  UPDATE public.scheduled_slots SET state='running',attempt_token=worker_token,lease_until=clock_timestamp()+interval '30 minutes',
   claims=claims+1,actual_start=coalesce(actual_start,clock_timestamp()),run_id=workflow_run,commit_sha=sha WHERE id=slot.id;
  RETURN jsonb_build_object('outcome','claimed','slot',public.ofir_scheduled_report(slot.id),'expired_slots',expired);
 END LOOP;
 RETURN jsonb_build_object('outcome','skipped','reason','no_eligible_work','slot',CASE WHEN EXISTS(SELECT 1 FROM public.scheduled_slots) THEN public.ofir_scheduled_report((SELECT id FROM public.scheduled_slots ORDER BY target_at DESC LIMIT 1)) END,'expired_slots',expired);
END;
$$;

CREATE OR REPLACE FUNCTION public.ofir_prepare_scheduled(slot_id TEXT, worker_token TEXT, expansion_ids JSONB)
RETURNS JSONB LANGUAGE plpgsql SET search_path='' AS $$
DECLARE slot public.scheduled_slots; selected JSONB; enabled_count INTEGER;
BEGIN
 SELECT * INTO STRICT slot FROM public.scheduled_slots WHERE id=slot_id FOR UPDATE;
 PERFORM pg_catalog.pg_advisory_xact_lock(4801739);
 IF slot.attempt_token IS DISTINCT FROM worker_token OR slot.state<>'running' OR slot.lease_until<=clock_timestamp() OR slot.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION 'Scheduled lease lost'; END IF;
 IF slot.company_ids IS NULL THEN
  IF jsonb_array_length(expansion_ids)>1 THEN RAISE EXCEPTION 'Expand by at most one source'; END IF;
  PERFORM public.ofir_enable_sources(expansion_ids);
  SELECT coalesce(jsonb_agg(id),'[]') INTO selected FROM (
   SELECT c.id FROM public.companies c WHERE enabled=1 AND NOT EXISTS(
    SELECT 1 FROM public.company_monitor_controls m WHERE m.company_id=c.id AND m.opted_out=1)
   ORDER BY (last_checked IS NOT NULL),last_checked,id LIMIT 20
  ) choices;
  SELECT count(*) INTO enabled_count FROM public.companies WHERE enabled=1;
  UPDATE public.scheduled_slots SET company_ids=selected,deferred_count=greatest(0,enabled_count-jsonb_array_length(selected)) WHERE id=slot_id;
 END IF;
 RETURN public.ofir_scheduled_report(slot_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.ofir_begin_scheduled_company(slot_id TEXT, worker_token TEXT, company TEXT)
RETURNS JSONB LANGUAGE plpgsql SET search_path='' AS $$
DECLARE slot public.scheduled_slots; item JSONB; scan public.scans;
BEGIN
 SELECT * INTO STRICT slot FROM public.scheduled_slots WHERE id=slot_id FOR UPDATE;
 IF slot.attempt_token IS DISTINCT FROM worker_token OR slot.state<>'running' OR slot.lease_until<=clock_timestamp() OR slot.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION 'Scheduled lease lost'; END IF;
 SELECT * INTO scan FROM public.scans WHERE scheduled_slot_id=slot_id AND company_id=company AND scheduled_attempt=worker_token;
 IF FOUND THEN RETURN to_jsonb(scan); END IF;
 SELECT d INTO item FROM jsonb_array_elements(public.ofir_scheduled_report(slot_id)->'companies') d WHERE d->>'company_id'=company;
 IF item IS NULL OR item->>'state'<>'ready' THEN RETURN jsonb_build_object('status','skipped'); END IF;
 INSERT INTO public.scans(company_id,started_at,status,scheduled_slot_id,scheduled_attempt)
 VALUES(company,clock_timestamp()::text,'running',slot_id,worker_token) RETURNING * INTO scan;
 UPDATE public.scheduled_slots SET lease_until=clock_timestamp()+interval '30 minutes' WHERE id=slot_id;
 RETURN to_jsonb(scan);
END;
$$;

CREATE OR REPLACE FUNCTION public.ofir_checkpoint_scheduled(slot_id TEXT, worker_token TEXT, company TEXT,
 result JSONB, payload JSONB)
RETURNS JSONB LANGUAGE plpgsql SET search_path='' AS $$
DECLARE slot public.scheduled_slots; scan public.scans; inserted INTEGER; updated INTEGER; receipt JSONB;
 attempt_count INTEGER; stamp TIMESTAMPTZ; next_retry TIMESTAMPTZ; is_retryable BOOLEAN;
BEGIN
 SELECT * INTO STRICT slot FROM public.scheduled_slots WHERE id=slot_id FOR UPDATE;
 SELECT * INTO STRICT scan FROM public.scans WHERE scheduled_slot_id=slot_id AND company_id=company AND scheduled_attempt=worker_token;
 IF scan.checkpoint_receipt IS NOT NULL THEN RETURN scan.checkpoint_receipt; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(4801739);
 stamp:=clock_timestamp();
 IF slot.attempt_token IS DISTINCT FROM worker_token OR slot.state<>'running' OR slot.lease_until<=stamp OR slot.deadline_at<=stamp THEN RAISE EXCEPTION 'Scheduled lease lost'; END IF;
 IF scan.status<>'running' OR result->>'status' NOT IN ('ok','empty','error','blocked','unsupported') OR result->>'status' IS NULL THEN RAISE EXCEPTION 'Invalid scheduled result'; END IF;
 -- Only this company's collection data may be written. Never replay application imports or restored feedback.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(payload->'companies','[]')) r WHERE r->>'id' IS DISTINCT FROM company)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(payload->'jobs','[]')) r WHERE r->>'company_id' IS DISTINCT FROM company)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(payload->'job_events','[]')) e WHERE NOT EXISTS(
   SELECT 1 FROM jsonb_array_elements(coalesce(payload->'jobs','[]')) j WHERE j->>'id'=e->>'job_id')) THEN RAISE EXCEPTION 'Checkpoint company mismatch'; END IF;
 -- Count actual accepted inserts/updates using the same guards as ofir_sync, under its advisory lock.
 SELECT count(*) FILTER(WHERE old.id IS NULL), count(*) FILTER(WHERE old.id IS NOT NULL
   AND j.last_seen_at>=old.last_seen_at AND (coalesce(old.match_version,'')='' OR coalesce(j.match_version,'')<>'')
   AND (to_jsonb(old)-ARRAY['fit','familiar','application_status','personal_note','user_updated_at','first_seen_at']) IS DISTINCT FROM
       ((to_jsonb(j)||jsonb_build_object(
         'match_category',coalesce(j.match_category,old.match_category),
         'match_version',coalesce(j.match_version,old.match_version),
         'match_details',coalesce(j.match_details,old.match_details)))
         -ARRAY['fit','familiar','application_status','personal_note','user_updated_at','first_seen_at']))
 INTO inserted,updated FROM jsonb_populate_recordset(NULL::public.jobs,coalesce(payload->'jobs','[]')) j LEFT JOIN public.jobs old ON old.id=j.id;
 PERFORM public.ofir_sync(jsonb_build_object('companies',coalesce(payload->'companies','[]'),
  'jobs',coalesce(payload->'jobs','[]'),'job_events',coalesce(payload->'job_events','[]')));
 PERFORM public.ofir_link_discoveries();
 SELECT count(*) INTO attempt_count FROM public.scans WHERE scheduled_slot_id=slot_id AND company_id=company;
 is_retryable:=coalesce((result->>'retryable')::boolean,false);
 next_retry:=CASE WHEN is_retryable THEN stamp+make_interval(secs=>greatest(
  CASE WHEN attempt_count=1 THEN 3600 ELSE 10800 END,least(86400,greatest(0,coalesce((result->>'retry_after_seconds')::integer,0))))) END;
 receipt:=jsonb_build_object('inserted',inserted,'updated',updated,'persistence','confirmed','company_id',company,'attempt',worker_token);
 UPDATE public.scans SET finished_at=stamp::text,status=result->>'status',fetched_count=(result->>'fetched_count')::integer,
  eligible_count=(result->>'eligible_count')::integer,new_count=(result->>'new_count')::integer,message=result->>'message',
  retry_kind=CASE WHEN result->>'status' IN ('ok','empty') THEN 'success' WHEN is_retryable THEN 'transient' ELSE 'permanent' END,
  retry_after=next_retry,checkpoint_receipt=receipt WHERE id=scan.id;
 UPDATE public.scheduled_slots SET lease_until=stamp+interval '30 minutes' WHERE id=slot_id;
 RETURN receipt;
END;
$$;

CREATE OR REPLACE FUNCTION public.ofir_finish_scheduled(slot_id TEXT, worker_token TEXT)
RETURNS JSONB LANGUAGE plpgsql SET search_path='' AS $$
DECLARE slot public.scheduled_slots; report JSONB; outcome TEXT;
BEGIN
 SELECT * INTO STRICT slot FROM public.scheduled_slots WHERE id=slot_id FOR UPDATE;
 IF slot.attempt_token IS DISTINCT FROM worker_token THEN RAISE EXCEPTION 'Scheduled lease lost'; END IF;
 IF slot.state IN ('completed','failed','retry_wait') THEN RETURN public.ofir_scheduled_report(slot_id); END IF;
 IF slot.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'Scheduled lease lost'; END IF;
 report:=public.ofir_scheduled_report(slot_id);
 outcome:=CASE WHEN slot.deadline_at<=clock_timestamp() THEN 'failed'
  WHEN (report->>'pending_retry')::integer>0 THEN 'retry_wait'
  WHEN (report->>'exhausted')::integer>0 OR slot.company_ids IS NULL OR (report->>'selected')::integer=0 THEN 'failed' ELSE 'completed' END;
 UPDATE public.scheduled_slots SET state=outcome,lease_until=NULL,
  finished_at=CASE WHEN outcome IN ('completed','failed') THEN clock_timestamp() END WHERE id=slot_id;
 RETURN public.ofir_scheduled_report(slot_id);
END;
$$;

REVOKE ALL ON FUNCTION public.ofir_scheduled_report(TEXT),public.ofir_claim_scheduled(TEXT,TEXT,TEXT),
 public.ofir_prepare_scheduled(TEXT,TEXT,JSONB),public.ofir_begin_scheduled_company(TEXT,TEXT,TEXT),
 public.ofir_checkpoint_scheduled(TEXT,TEXT,TEXT,JSONB,JSONB),public.ofir_finish_scheduled(TEXT,TEXT) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ofir_scheduled_report(TEXT),public.ofir_claim_scheduled(TEXT,TEXT,TEXT),
 public.ofir_prepare_scheduled(TEXT,TEXT,JSONB),public.ofir_begin_scheduled_company(TEXT,TEXT,TEXT),
 public.ofir_checkpoint_scheduled(TEXT,TEXT,TEXT,JSONB,JSONB),public.ofir_finish_scheduled(TEXT,TEXT) TO service_role;


SELECT private.configure_owner(current_setting('ofir.setup_email'));


